CREATE TABLE recovery_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),evidence jsonb NOT NULL,result jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now()
)

CREATE TABLE ezviz_connection_versions (
 connection_id uuid NOT NULL REFERENCES ezviz_connections(id),version integer NOT NULL,snapshot jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(connection_id,version)
)

CREATE TABLE subsidy_expenses (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),object_id uuid NOT NULL REFERENCES objects(id),claim_id uuid NOT NULL REFERENCES subsidy_claims(id),expense_id uuid NOT NULL REFERENCES business_expenses(id),active boolean NOT NULL DEFAULT true,UNIQUE(claim_id,expense_id)
)

