CREATE FUNCTION identity_bump_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF ROW(NEW.password_hash,NEW.role,NEW.enabled,NEW.wecom_corp_id,NEW.wecom_user_id)
     IS DISTINCT FROM ROW(OLD.password_hash,OLD.role,OLD.enabled,OLD.wecom_corp_id,OLD.wecom_user_id) THEN
    NEW.auth_version := OLD.auth_version + 1;
  END IF;
  RETURN NEW;
END;
$$

CREATE FUNCTION preserve_measurement() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Raw evidence is append-only' USING ERRCODE='55000'; END;
$$

CREATE FUNCTION preserve_finished_management() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF OLD.state='complete' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Completed report snapshot is immutable' USING ERRCODE='55000'; END IF; RETURN NEW; END;
$$
